{
  "architecture_decisions": [
    {
      "dimension": "Context Management",
      "recommendation": "Introduce a dedicated cancellable context for heartbeat operations managed by the worker lifecycle.",
      "rationale": "Using a dedicated context allows precise control over heartbeat cancellation during worker shutdown, preventing hanging RPCs and ensuring clean teardown. It also enables future observability enhancements (e.g., tracing heartbeat lifecycle).",
      "alternatives_considered": [
        "Reuse the worker’s main context (risky if it’s shared with other long-lived operations)",
        "Use context.WithTimeout for heartbeats (insufficient for abrupt shutdown needs)",
        "No change (leaves shutdown race conditions unaddressed)"
      ],
      "files_affected": [
        "internal/internal_worker_heartbeat.go",
        "worker/worker.go"
      ]
    },
    {
      "dimension": "Shutdown Order",
      "recommendation": "Cancel the heartbeat context before initiating other shutdown steps in Worker.Stop().",
      "rationale": "This ensures that in-flight heartbeat RPCs are interrupted before the worker begins tearing down other components (like activity pollers or workflow task handlers), preventing deadlocks or prolonged shutdown times.",
      "alternatives_considered": [
        "Cancel heartbeat context after other shutdown steps (risks hanging shutdown)",
        "Cancel concurrently with other steps (potential race condition)",
        "No explicit ordering (unreliable shutdown behavior)"
      ],
      "files_affected": [
        "worker/worker.go",
        "internal/internal_worker_heartbeat.go"
      ]
    },
    {
      "dimension": "Error Handling",
      "recommendation": "Handle context.Canceled errors from RecordWorkerHeartbeat gracefully in heartbeat logic, treating them as expected shutdown signals rather than failure conditions.",
      "rationale": "This prevents logging unnecessary errors during normal shutdown and allows the worker to proceed with cleanup without retry or panic.",
      "alternatives_considered": [
        "Log context.Canceled as warnings (clutters logs during normal shutdown)",
        "Ignore all errors from heartbeat (obscures real failures)",
        "Retry on context.Canceled (counterproductive and wasteful)"
      ],
      "files_affected": [
